const d = $json.body ?? $json;
const alerts = Array.isArray(d.alerts) ? d.alerts.filter(Boolean) : [];
const fallbackAlert = (d.alert_triggered || d.alert_reason || d.alert_severity)
  ? [{
      type: d.alert_type ?? 'ALERT',
      severity: d.alert_severity ?? 'warning',
      message: d.alert_reason ?? 'Queue alert',
      value: d.estimated_wait_sec ?? d.metrics?.wait_time_seconds ?? null,
      threshold: null,
    }]
  : [];
const effectiveAlerts = alerts.length > 0 ? alerts : fallbackAlert;
const primaryAlert = effectiveAlerts[0] ?? null;
const alertType = primaryAlert?.type ?? 'ALERT';
const severity = primaryAlert?.severity ?? d.alert_severity ?? 'warning';
const zoneId = d.zone_id ?? d.feed_id ?? 'unknown';
const cooldownSeconds = 120;
const now = Date.now();
const staticData = getWorkflowStaticData('global');
staticData.alertCooldowns ??= {};
const cooldownKey = `${zoneId}:${alertType}:${severity}`;
const lastSentAt = staticData.alertCooldowns[cooldownKey] ?? 0;
const shouldSendTelegram = d.force_telegram ? true : (!lastSentAt || (now - lastSentAt) >= cooldownSeconds * 1000);
const cooldownRemainingSeconds = shouldSendTelegram ? 0 : Math.max(0, Math.ceil((cooldownSeconds * 1000 - (now - lastSentAt)) / 1000));
if (shouldSendTelegram) {
  staticData.alertCooldowns[cooldownKey] = now;
}
return [{ json: { ...d, alerts: effectiveAlerts, primary_alert: primaryAlert, alert_type: alertType, alert_severity: severity, send_telegram: shouldSendTelegram, cooldown_seconds: cooldownSeconds, cooldown_remaining_seconds: cooldownRemainingSeconds, cooldown_key: cooldownKey } }];

